249		proc.Stdout = logs
250		proc.Stderr = logs
251		if err := proc.Start(); err != nil {
252			t.Fatal(err)
253		}
254		done := make(chan error, 1)
255		go func() { done <- proc.Wait() }()
256		ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
257		defer cancel()
258		select {
259		case err := <-done:
260			if err == nil {
261				t.Fatal("an illegal handover record must prevent startup")
262			}
263			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
264				t.Fatalf("startup must exit non-zero: %v", err)
265			}
266		case <-ctx.Done():
267			proc.Process.Kill()
268			t.Fatalf("server stayed up despite an illegal handover record; output:\n%s", logs.String())
269		}
270	
271		out := logs.String()
272		for _, fragment := range want {
273			if !strings.Contains(out, fragment) {
274				t.Fatalf("startup error must contain %q:\n%s", fragment, out)
275			}
276		}
277		if strings.Contains(out, "listening on") {
278			t.Fatalf("failed startup must not announce readiness:\n%s", out)
279		}
