81	// startServer launches serve on an ephemeral port and blocks until the
82	// readiness line publishes the real address — no fixed sleeps.
83	func startServer(t *testing.T, dataDir string) *serverProc {
84		t.Helper()
85		logs := &safeBuffer{}
86		cmd := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
87		stdout, err := cmd.StdoutPipe()
88		if err != nil {
